{
  "rules": [
    {
      "id": "D_NONNEG_ALL",
      "description": "All numeric values should be nonnegative.",
      "gx_code": "gx.expectations.ExpectAllValuesToBeNonNegative",
      "evidence_references": [
        "Nonnegative concentration, density, percentage or pH; no clean-test range fitting."
      ]
    },
    {
      "id": "D_PH_RANGE",
      "description": "pH values should be within the conventional aqueous pH screening range.",
      "gx_code": "gx.expectations.ExpectColumnValuesToBeBetween",
      "evidence_references": [
        "Conventional aqueous pH screening range, not an empirical min/max."
      ],
      "kwargs": {
        "min_value": 0,
        "max_value": 14
      }
    },
    {
      "id": "D_TOTAL_SULFUR",
      "description": "Total sulfur dioxide should be greater than or equal to free sulfur dioxide.",
      "gx_code": "gx.expectations.ExpectColumnValuesToBeGreaterThan",
      "evidence_references": [
        "Free sulfur is a component of total sulfur; laboratory measurement uncertainty can cause violations."
      ],
      "kwargs": {
        "column": "total sulfur dioxide",
        "threshold": "free sulfur dioxide"
      }
    }
  ],
  "abstentions": [
    "D_FREE_TOTAL",
    "D_NONNEG_{i}"
  ]
}
